D['chart-stack']='''R{display:flex;align-items:stretch;gap:var(--gap);padding-bottom:var(--gap-lg);} R .sbar{flex:1;display:flex;flex-direction:column-reverse;justify-content:flex-start;position:relative;} R .sbar>span{position:absolute;top:calc(100% + var(--gap-sm));width:100%;text-align:center;font-size:var(--type-18);} R .seg{height:calc(var(--v)/var(--max,100)*100%);background:var(--a1);display:grid;place-items:center;color:var(--a1-on);border-top:2px solid var(--page);} R .seg.tone-2{background:var(--a2);color:var(--a2-on);} R .seg.tone-3{background:var(--a3);color:var(--a3-on);} R .seg.tone-4{background:var(--a4);color:var(--a4-on);} R b{font-size:var(--type-20);font-weight:var(--figure-weight);} R.h{flex-direction:column;padding-left:calc(var(--gap-lg)*2);padding-bottom:0;} R.h .sbar{flex-direction:row;} R.h .sbar>span{left:calc(var(--gap-lg)*-2);top:35%;width:var(--gap-lg);} R.h .seg{width:calc(var(--v)/var(--max,100)*100%);height:100%;border-top:0;border-right:2px solid var(--page);} @container (max-width:650px){R{gap:var(--gap-sm);} R b{font-size:var(--type-16);} R .sbar>span{font-size:var(--type-14);}}'''
D['chart-waterfall']='''R{display:flex;gap:var(--gap);padding:var(--gap-lg) 0;} R .move{position:relative;flex:1;min-width:0;} R .move::before{content:'';position:absolute;left:0;right:0;bottom:calc(min(var(--from),var(--to))/var(--max)*100%);height:calc(abs(var(--to) - var(--from))/var(--max)*100%);background:var(--n-4);border-radius:var(--radius-sm) var(--radius-sm) 0 0;} R .up::before{background:var(--a1);} R .down::before{background:var(--n-5);} R .total::before{bottom:0;height:calc(var(--to)/var(--max)*100%);background:var(--a1);} R .move::after{content:'';position:absolute;left:100%;width:var(--gap);bottom:calc(var(--to)/var(--max)*100%);border-top:var(--stroke) dashed var(--n-5);} R .move:last-child::after{display:none;} R b{position:absolute;left:0;right:0;bottom:calc(max(var(--from),var(--to))/var(--max)*100% + var(--gap-sm));text-align:center;font-size:var(--type-22);font-weight:var(--figure-weight);} R span{position:absolute;left:0;right:0;bottom:calc(var(--gap-lg)*-1);text-align:center;font-size:var(--type-16);} @container (max-width:650px){R{gap:var(--gap-sm);} R b{font-size:var(--type-16);} R span{font-size:var(--type-14);}}'''
