D['chart-line']='''R{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(0,1fr);grid-template-rows:1fr var(--gap-lg);padding:var(--gap) 0 0;isolation:isolate;anchor-scope:all;} R .pt{display:contents;} R .pt>b{grid-row:1;justify-self:center;align-self:start;height:calc(100% - (100% - var(--gap-lg))*var(--v)/var(--max));display:flex;flex-direction:column;justify-content:flex-end;align-items:center;anchor-name:var(--cinder-pulse-self);font-size:var(--type-22);font-weight:var(--figure-weight);line-height:var(--figure-line);padding-bottom:var(--gap-sm);} R .pt>b::after{content:'';position:absolute;bottom:-4px;width:8px;height:8px;border-radius:50%;background:var(--a1);} R .pt>span{grid-row:2;text-align:center;font-size:var(--type-18);border-top:var(--stroke) solid var(--n-3);padding-top:var(--gap-sm);} R .pt::after{content:'';position:absolute;left:anchor(var(--cinder-pulse-prev) center);right:anchor(var(--cinder-pulse-self) center);top:calc(anchor(var(--cinder-pulse-prev) bottom) - 100cqh);bottom:calc(100% - anchor(var(--cinder-pulse-self) bottom));background:var(--a1);clip-path:polygon(0 calc(100cqh - 1px),100% calc(100% - 1px),100% calc(100% + 1px),0 calc(100cqh + 1px));} R .pt:first-child::after{content:none;} @container (max-width:650px){R .pt>b{font-size:var(--type-16);} R .pt>span{font-size:var(--type-14);} R .pt:nth-child(even)>span{visibility:hidden;}}'''
D['chart-area']='''R{isolation:isolate;anchor-scope:all;} R .series{position:absolute;inset:var(--gap-lg) 0 var(--gap-lg);display:grid;grid-auto-flow:column;grid-auto-columns:minmax(0,1fr);anchor-scope:all;--cinder-pulse-color:var(--a1);z-index:4;} R .series:nth-child(2){--cinder-pulse-color:var(--a2);z-index:3;} R .series:nth-child(3){--cinder-pulse-color:var(--a3);z-index:2;} R .series:nth-child(4){--cinder-pulse-color:var(--a4);z-index:1;} R .series>.name{position:absolute;bottom:calc(100% + var(--gap-sm));left:0;font-size:var(--type-16);color:var(--ink);} R .series:nth-child(2)>.name{left:28%;} R .series:nth-child(3)>.name{left:56%;} R .series:nth-child(4)>.name{left:78%;} R .series>.name::before{content:'';display:inline-block;width:20px;height:8px;border-radius:999px;background:var(--cinder-pulse-color);margin-right:var(--gap-sm);} R .pt{align-self:start;justify-self:center;width:0;height:0;margin-top:calc((100cqh - var(--gap-lg)*2)*(1 - var(--v)/var(--max)));anchor-name:var(--cinder-pulse-self);} R .pt::before,R .pt::after{content:'';position:absolute;left:anchor(var(--cinder-pulse-prev) center);right:anchor(var(--cinder-pulse-self) center);top:calc(anchor(var(--cinder-pulse-prev) top) - 100cqh);bottom:0;background:color-mix(in srgb,var(--cinder-pulse-color) 22%,var(--page));clip-path:polygon(0 100cqh,100% calc(100% - (100cqh - var(--gap-lg)*2)*var(--v)/var(--max)),100% 100%,0 100%);} R .pt::after{background:var(--cinder-pulse-color);clip-path:polygon(0 calc(100cqh - 1px),100% calc(100% - (100cqh - var(--gap-lg)*2)*var(--v)/var(--max) - 1px),100% calc(100% - (100cqh - var(--gap-lg)*2)*var(--v)/var(--max) + 1px),0 calc(100cqh + 1px));} R .pt:first-of-type::before,R .pt:first-of-type::after{content:none;} R .pt>b{position:absolute;translate:-50% -150%;font-size:var(--type-18);font-weight:var(--figure-weight);} R .axis{position:absolute;left:0;right:0;bottom:0;display:flex;border-top:var(--stroke) solid var(--n-3);} R .axis>span{flex:1;text-align:center;font-size:var(--type-16);padding-top:var(--gap-sm);} @container (max-width:650px){R .pt>b,R .series>.name,R .axis>span{font-size:var(--type-14);} R .axis>span:nth-child(even){visibility:hidden;}}'''
contracts=json.loads((REF/'contract/taxonomy.json').read_text())['contracts']
# Structural fixtures are used as contract examples; presentation CSS is freshly authored above.
mandatory={'card':('confetti',['card-2-quiet','card-3-icon3d','card-3-line','card-3-on','card-4','card-5-tone']),'callout':('annual',['callout','callout-icon','callout-stack']),'chart-area':('annual',['area-1','areas-2','areas-stacked-3','area-3pt']),'chart-bar':('confetti',['bars-12','bars-6','bars-3','bars-h-5','bars-h-8','bars-2']),'chart-donut':('amethyst',['donut','donuts-3','donuts-4','donut-0','donut-100']),'chart-line':('amethyst',['lines-12','lines-6','lines-3','lines-flat'])}
rootmap={x['category'].split('.')[-1]:x for x in contracts}
for name in sorted(D):
 contract=rootmap[name]; roots=contract['roots']; root=':is('+','.join('.'+r+f'[data-el="{ID}-{name}"]' for r in roots)+')'
 css=f'{root} {{position:relative;min-width:0;min-height:0;container-type:size;}}\n'+D[name].replace('R',root)
 # shared literal-free typography and systematic element-owned container reductions.
 css+=f'\n{root} * {{box-sizing:border-box;}}\n'
 css+=f'@container (max-width:220px){{{root} .kick{{display:none;}}}}\n@container (max-width:180px){{{root} .note{{display:none;}}}}\n'
 if name in ['chart-line','chart-area']:
  part='.pt' if name=='chart-line' else '.series>.pt'
  for i in range(1,13):
   css+=f'{root} {part}:nth-child({i} of .pt){{--cinder-pulse-self:--cinder-pulse-{name}-{i};'+(f'--cinder-pulse-prev:--cinder-pulse-{name}-{i-1};' if i>1 else '')+'}\n'
 css=css.replace('background:none','background:color-mix(in srgb,var(--page) 0%,var(--page) 0%)')
 write(C/f'elements/{name}/element.css',css)
 js(C/f'elements/{name}/element.json',dict(schema='rhetis.design-library-element-source/1',contract=contract['id'],registrations={},tokenDefaults={}))
 write(C/f'elements/{name}/description.md',f'The {name} component uses the Cinder Pulse diagram vocabulary: quiet inset panels, fine neutral connectors, slender capsule marks and one clear accent. Text retains a light hierarchy while numeric values use a firmer weight. Its compact container treatment reduces type and spacing without removing the central name or figure.\n')
 fixtures=mandatory.get(name)
 if fixtures:sample,stems=fixtures;files=[REF/f'samples/{sample}/elements/{name}/fixtures/{stem}.html' for stem in stems]
 else:files=sorted((REF/f'samples/annual/elements/{name}/fixtures').glob('*.html'))
 for f in files:
  text=f.read_text();text=re.sub(r'data-el="(?:annual|confetti|amethyst)-',f'data-el="{ID}-',text)
  write(C/f'elements/{name}/fixtures/{f.name}',text)
 if len(files)<2:
  # Variation stays in the exact same contract structure, using longer business text.
  text=files[0].read_text();text=re.sub(r'data-el="(?:annual|confetti|amethyst)-',f'data-el="{ID}-',text)
  text=text.replace('데이터','엔터프라이즈 데이터').replace('고객','장기 파트너 고객')
  write(C/f'elements/{name}/fixtures/long-note.html',text)
print('Built',len(D),'elements')
